#!/root/.venv/bin/python
import os
import re
import sys
import time
import json
import requests
import urllib3
from bs4 import BeautifulSoup

urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

ESSAYS = [
    {
        "title": "Do Things that Don't Scale",
        "url": "https://paulgraham.com/ds.html",
    },
    {
        "title": "Founder Mode",
        "url": "https://www.paulgraham.com/foundermode.html",
    },
]

OUT_DIR = "/root/tts_chunks"
AUDIOBOOK = "/root/audiobook.mp3"
MODEL = "gpt-4o-mini-tts"
VOICE = "alloy"
MAX_CHARS = 3500

SKIP_EXACT = {
    "Want to start a startup?",
    "Get funded by",
    "Y Combinator",
    ".",
}


def fetch_html(url: str) -> str:
    try_urls = [url]
    if url.startswith("https://"):
        try_urls.append("http://" + url[len("https://"):])
    for u in try_urls:
        try:
            resp = requests.get(u, timeout=30, verify=False)
            resp.raise_for_status()
            return resp.text
        except Exception:
            last_err = sys.exc_info()[1]
            continue
    raise RuntimeError(f"Failed to fetch {url}: {last_err}")


def extract_text(html: str) -> str:
    soup = BeautifulSoup(html, "html.parser")
    for tag in soup(["script", "style", "noscript"]):
        tag.decompose()
    body = soup.body or soup
    raw = body.get_text("\n", strip=True)
    lines = [l.strip() for l in raw.splitlines()]

    cleaned = []
    for line in lines:
        if not line:
            if cleaned and cleaned[-1] != "":
                cleaned.append("")
            continue
        if line in SKIP_EXACT:
            continue
        if line.lower().startswith("image"):
            if ":" in line:
                maybe = line.split(":", 1)[1].strip()
                if maybe:
                    cleaned.append(maybe)
            continue
        if re.fullmatch(r"\[|\]|\d+|\[\d+\]", line):
            continue
        line = re.sub(r"\[\d+\]", "", line)
        line = re.sub(r"\s{2,}", " ", line)
        cleaned.append(line)

    text = "\n".join(cleaned)
    text = re.sub(r"\n{3,}", "\n\n", text).strip()
    return text


def chunk_text(text: str, max_chars: int = MAX_CHARS):
    paras = [p.strip() for p in text.split("\n\n") if p.strip()]
    chunks = []
    buf = ""

    def flush_buf():
        nonlocal buf
        if buf:
            chunks.append(buf)
            buf = ""

    for p in paras:
        if len(p) > max_chars:
            flush_buf()
            sentences = re.split(r"(?<=[.!?])\s+", p)
            sub = ""
            for s in sentences:
                if len(s) > max_chars:
                    if sub:
                        chunks.append(sub)
                        sub = ""
                    for i in range(0, len(s), max_chars):
                        chunks.append(s[i:i + max_chars])
                    continue
                if sub and len(sub) + 1 + len(s) <= max_chars:
                    sub = sub + " " + s
                else:
                    if sub:
                        chunks.append(sub)
                    sub = s
            if sub:
                chunks.append(sub)
            continue

        if not buf:
            buf = p
        elif len(buf) + 2 + len(p) <= max_chars:
            buf = buf + "\n\n" + p
        else:
            flush_buf()
            buf = p

    flush_buf()
    return chunks


def tts_to_file(text: str, out_path: str, api_key: str):
    payload = {
        "model": MODEL,
        "voice": VOICE,
        "input": text,
        "response_format": "mp3",
    }
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }
    resp = requests.post(
        "https://api.openai.com/v1/audio/speech",
        headers=headers,
        data=json.dumps(payload),
        timeout=120,
    )
    if resp.status_code != 200:
        raise RuntimeError(f"TTS failed: {resp.status_code} {resp.text[:500]}")
    with open(out_path, "wb") as f:
        f.write(resp.content)


def main():
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError("OPENAI_API_KEY is not set")

    os.makedirs(OUT_DIR, exist_ok=True)
    segment_paths = []

    for idx, essay in enumerate(ESSAYS, start=1):
        html = fetch_html(essay["url"])
        text = extract_text(html)

        title = essay["title"]
        if not text.lower().startswith(title.lower()):
            text = f"{title}\n\n{text}"

        chunks = chunk_text(text)
        for c_idx, chunk in enumerate(chunks, start=1):
            out_path = os.path.join(OUT_DIR, f"{idx:02d}_{c_idx:03d}.mp3")
            tts_to_file(chunk, out_path, api_key)
            segment_paths.append(out_path)
            time.sleep(0.2)

    list_path = os.path.join(OUT_DIR, "list.txt")
    with open(list_path, "w") as f:
        for p in segment_paths:
            f.write(f"file '{p}'\n")

    os.system(f"ffmpeg -y -f concat -safe 0 -i '{list_path}' -c copy '{AUDIOBOOK}' > /dev/null 2>&1")

    if not os.path.exists(AUDIOBOOK):
        raise RuntimeError("Failed to create audiobook")


if __name__ == "__main__":
    main()
